<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import ColumnStrip from '@/components/designer/ColumnStrip.vue'
import FieldPicker from '@/components/designer/FieldPicker.vue'
import ExpressionEditor from '@/components/designer/ExpressionEditor.vue'
import FooterEditor from '@/components/designer/FooterEditor.vue'
import SummaryEditor from '@/components/designer/SummaryEditor.vue'
import PageSetupPanel from '@/components/designer/PageSetupPanel.vue'
import RevisionsDrawer from '@/components/designer/RevisionsDrawer.vue'
import DocumentPreview from '@/components/documents/DocumentPreview.vue'
import { api, ApiError, errorMessage } from '@/lib/api'
import { designerMessages as m } from '@/lib/messages/designer'
import type { DocumentTemplate, DocumentColumn, DocumentSheet, RenderDocument, LayoutIssue } from '@/lib/types/documents'
const props = defineProps<{ templateId: string }>()
const template = ref<DocumentTemplate | null>(null), selected = ref(''), fields = ref<{ key: string; label: string; scope: string }[]>([])
const shipments = ref<{ id: string; title: string }[]>([]), shipmentId = ref(''), preview = ref<RenderDocument | null>(null)
const error = ref(''), success = ref(''), busy = ref(false), issues = ref<LayoutIssue[]>([]), advanced = ref('')
const main = computed(() => template.value?.layout.sheets.find(s => s.role === 'main'))
const column = computed(() => main.value?.columns.find(c => c.key === selected.value))
const expression = computed({ get: () => column.value?.expr ?? '', set: value => { if (column.value) { column.value.expr = value || undefined; if (value) delete column.value.field } } })
const summary = computed({ get: () => template.value?.layout.sheets.find(s => s.role === 'summary') ?? null, set: (value: DocumentSheet | null) => { if (template.value) template.value.layout.sheets = [...template.value.layout.sheets.filter(s => s.role !== 'summary'), ...(value ? [value] : [])] } })
function accept(value: DocumentTemplate) { template.value = value; selected.value = value.layout.sheets.find(s => s.role === 'main')?.columns[0]?.key ?? ''; advanced.value = JSON.stringify(value.layout, null, 2) }
function fail(e: unknown) { error.value = e instanceof ApiError && e.status === 409 ? m.conflict : errorMessage(e); issues.value = e instanceof ApiError && Array.isArray(e.body?.errors) ? e.body.errors as unknown as LayoutIssue[] : [] }
async function save() { if (!template.value) return; busy.value = true; error.value = ''; success.value = ''; try { accept(await api.put(`/api/document-templates/${props.templateId}`, { name: template.value.name, layout: template.value.layout, version: template.value.version })); success.value = m.saved } catch (e) { fail(e) } finally { busy.value = false } }
async function showPreview() { if (!template.value || !shipmentId.value) return; try { preview.value = await api.post('/api/document-templates/preview', { shipmentId: shipmentId.value, layout: template.value.layout }) } catch (e) { fail(e) } }
async function reset() { if (!template.value) return; try { accept(await api.post(`/api/document-templates/${props.templateId}/reset`, { version: template.value.version })); success.value = m.saved } catch (e) { fail(e) } }
function addColumn() { if (!main.value) return; const key = `computed${main.value.columns.length + 1}`; const col: DocumentColumn = { key, label: 'ستون تازه', width: 14, expr: '0', visibleWhen: 'always' }; main.value.columns.push(col); selected.value = key }
function applyAdvanced() { if (!template.value) return; try { template.value.layout = JSON.parse(advanced.value); error.value = '' } catch { error.value = 'ساختار قالب درست نیست.' } }
onMounted(async () => { try { accept(await api.get(`/api/document-templates/${props.templateId}`)); fields.value = await api.get('/api/fields?purpose=document'); shipments.value = await api.get('/api/shipments'); shipmentId.value = shipments.value[0]?.id ?? '' } catch (e) { fail(e) } })
</script>
<template><section class="space-y-5" :aria-busy="busy"><a href="/settings/documents" class="inline-flex min-h-11 items-center text-primary">قالب‌های خروجی</a><h1 class="text-2xl font-bold">طراحی اکسل و چاپ</h1><p v-if="error" role="alert" class="text-error">{{ error }}</p><p v-if="success" role="status">{{ success }}</p><ul v-if="issues.length" role="alert"><li v-for="issue in issues" :key="issue.path + issue.message"><code dir="ltr">{{ issue.path }}</code> — {{ issue.message }}</li></ul><template v-if="template && main"><label class="block">نام قالب<input v-model="template.name" class="mt-2 min-h-11 w-full rounded-lg border border-outline-variant bg-surface p-3" /></label><div class="flex flex-wrap gap-3"><button class="min-h-11 rounded-lg bg-primary px-5 text-on-primary disabled:opacity-50" :disabled="busy" @click="save">{{ m.save }}</button><button class="min-h-11 rounded-lg border border-outline-variant px-5" @click="reset">{{ m.reset }}</button><button class="min-h-11 rounded-lg border border-outline-variant px-5" @click="addColumn">{{ m.add }}</button></div><ColumnStrip v-model="main.columns" :selected="selected" @select="selected = $event" /><div v-if="column" class="space-y-3 rounded-xl border border-outline-variant p-4"><h2 class="font-bold">{{ column.label }}</h2><label class="block">کلید ستون<input :value="column.key" readonly dir="ltr" class="min-h-11 w-full rounded border border-outline-variant bg-surface p-2" /></label><FieldPicker :fields="fields" @select="column.field = $event; delete column.expr" /><ExpressionEditor v-model="expression" :layout="template.layout" :column-key="column.key" :shipment-id="shipmentId" /><label class="block">قالب عددی<input v-model="column.format" dir="ltr" class="min-h-11 w-full rounded border border-outline-variant bg-surface p-2" placeholder="#,##0.00" /></label><button class="min-h-11 px-3 text-error" @click="main.columns = main.columns.filter(c => c.key !== selected); selected = main.columns[0]?.key ?? ''">حذف ستون</button></div><FooterEditor v-if="main.group" v-model="main.group.footer" :columns="main.columns" /><SummaryEditor v-model="summary" :footers="main.group?.footer" /><PageSetupPanel v-model="template.layout.page" /><RevisionsDrawer :template-id="templateId" :version="template.version" @restored="accept" /><label class="block">{{ m.preview }}<select v-model="shipmentId" class="min-h-11 w-full rounded border border-outline-variant bg-surface p-2"><option value="">محموله را انتخاب کنید</option><option v-for="s in shipments" :key="s.id" :value="s.id">{{ s.title }}</option></select></label><button :disabled="!shipmentId" class="min-h-11 rounded-lg border border-outline-variant px-5" @click="showPreview">پیش‌نمایش تغییرها</button><DocumentPreview :document="preview" /><details class="rounded-lg border border-outline-variant p-3"><summary class="min-h-11 cursor-pointer">ویرایش پیشرفتهٔ عنوان، سبک‌ها و ساختار قالب</summary><textarea v-model="advanced" dir="ltr" aria-label="ساختار کامل قالب" class="min-h-96 w-full rounded border border-outline-variant bg-surface p-3 font-mono" /><button class="min-h-11 px-4 text-primary" @click="applyAdvanced">اعمال ساختار</button></details></template></section></template>
